// AP Computer Science A — Java programming: basics, control structures, data structures. Spec for scripts/gen-us-elementary.cjs.
const P = (kind, name, statement) => [kind, name, statement];
const S = (reasoning, marks, markCode = "M", working) => ({ reasoning, marks, markCode, ...(working ? { working } : {}) });
const sumMarks = (steps) => steps.reduce((a, s) => a + s.marks, 0);
const mcq = (difficulty, stem, choices, correct, principles, steps, finalAnswer, commonErrors) => ({
  difficulty, totalMarks: sumMarks(steps), stem, choices, correct, principles, steps, finalAnswer, ...(commonErrors ? { commonErrors } : {}),
});
const num = (difficulty, stem, numeric, principles, steps, finalAnswer, commonErrors) => ({
  difficulty, totalMarks: sumMarks(steps), stem, numeric, principles, steps, finalAnswer, ...(commonErrors ? { commonErrors } : {}),
});
const op = (difficulty, stem, principles, steps, finalAnswer, commonErrors) => ({
  difficulty, totalMarks: sumMarks(steps), stem, principles, steps, finalAnswer, ...(commonErrors ? { commonErrors } : {}),
});
const lesson = (slug, title, goal, standards, vocab, concept) => ({ slug, title, goal, standards, vocab, concept });

